def longest_consecutive_sorted(a: list[int]) -> int:
    if not a:
        return 0
    s = sorted(set(a))
    best = run = 1
    for i in range(1, len(s)):
        run = run + 1 if s[i] == s[i - 1] + 1 else 1
        best = max(best, run)
    return best

def longest_consecutive(a: list[int]) -> int:
    s = set(a)
    best = 0
    for x in s:
        if x - 1 in s:
            continue
        length = 1
        cur = x
        while cur + 1 in s:
            cur += 1
            length += 1
        best = max(best, length)
    return best
